"""Narrative of deep-dive report D6 (impedance by imitation, ADR 0008); result sections are filled
from runs/d7 after the evaluations."""
import json as _json
import os as _os
from pathlib import Path

from experiments.d7_extras import (LABELS, REPORT, cue_table, fig_blocked_traces, fig_stiffness, load, sensing_table, stop_and_wait_table, training_curves)
from experiments.d_report import pooled

_metrics_path = Path(_os.environ.get("LLC_METRICS", "runs/d7/metrics_test.json"))
_data, _groups = load(_metrics_path) if _metrics_path.exists() else ({}, {})
ORDER = ["pd_shared", "pd_feedforward", "oracle_pd", "oracle_pd_residual_acmed_s02_lowrate-s0", "pd_residual_acmed_s02_lowrate", "ppo_contact_v2", "ppo_cap_gain", "ppo_cap_gain_ext",
         "distill_gain_ext", "distill_gain_ext_preview", "ppo_distill_gain_ext", "ppo_cap_gain_ext_anchor"]
METHODS = [(k, LABELS.get(k, k)) for k in ORDER if k in _groups.get("in_distribution", {})]
_keys = [k for k, _ in METHODS]
_episodes = Path(_os.environ.get("LLC_EPISODES", "runs/d7/episodes_test"))


def _blocked_case():
    rep = _data.get("representative_cases", {}).get("blocked")
    if rep is None:
        return ""
    from llc.eval.cases_v2 import make_case_v2
    from llc.sim.nominal import NominalModel

    idx = int(rep.split("-")[-1])
    case = make_case_v2("blocked", "test", idx, NominalModel())
    show = [k for k in ("pd_shared", "oracle_pd", "pd_residual_acmed_s02_lowrate-s0", "distill_gain_ext-s0", "ppo_distill_gain_ext-s0") if (_episodes / f"{rep}__{k}.npz").exists()]
    return fig_blocked_traces(_episodes, rep, show, case.meta["normal"], case.meta["surface"], case.meta["tool_ref"]) if show else ""


STOP_SECTION = ("<h2>Stop and wait: the oracle against the controllers</h2>\n<p>Blocked family, 16 in-distribution test cases, means over cases (seeds pooled). The oracle rows are privileged (they know the surface); they are the ceiling of the protocol and the teacher of the distilled students.</p>\n"
                + (stop_and_wait_table(_groups, _keys, "Blocked targets: the stop-and-wait metrics. Apparent stiffness: mean force per metre of reference depth; contact stiffness: per metre of the tool's actual error along the normal (a spring on the error).") if _groups else "")
                + _blocked_case()) if _groups else ""
STIFF_SECTION = ("<h2>Does the controller behave as a spring? Compliant surfaces</h2>\n<p>Held-out groups with the table and the wall replaced by a 2 kN/m and a 500 N/m surface (training stays on the rigid plant). A spring on the error keeps its stiffness on every surface until the force bound; a force setpoint does not.</p>\n"
                 + fig_stiffness(_groups, [k for k in _keys if k not in ("pd_feedforward", "ppo_contact_v2", "distill_gain_ext_preview")])) if _groups and "surface_500" in _groups else ""
CUE_SECTION = "<h2>Cue audit: what carries the contact information</h2>\n" + cue_table(Path("runs/d7/cue_audit.json"), "residual") + cue_table(Path("runs/d7/cue_audit.json"), "pd", caption="The same audit on episodes of the shared PD.")
_probes = [Path("runs/d7/probe.json"), Path("runs/d7/probe_stage2.json")]
SENSING_SECTION = ("<h2>Contact sensing of the learned controllers</h2>\n" + sensing_table(_probes, LABELS)) if any(p.exists() for p in _probes) else ""
_distill_runs = sorted(str(p) for p in Path("runs/d7").glob("distill_*-s*") if p.is_dir())
_ppo_runs = sorted(str(p) for p in Path("runs/d7").glob("ppo_*-s*") if p.is_dir())
TRAIN_SECTION = "<h2>Training</h2>\n" + (training_curves(_distill_runs, "iter", "DAgger iteration (0 = warm start)", "distill", "Distillation: validation on the 32 fixed cases under the cap after every DAgger iteration (iteration 0 is the warm start at 10 ms decisions); one line per seed. Gray dashed: the protocol PD on the same cases.", "fig-distill") if _distill_runs else "") \
    + (training_curves(_ppo_runs, "update", "PPO update", "ppo", "PPO fine-tuning under the cap with the stop-and-wait anchor: validation every 25 updates (the first point is the student itself).", "fig-ppo") if _ppo_runs else "")
_videos = REPORT / "data" / "videos.html"
VIDEO_SECTION = ("<h2>Representative episodes</h2>\n" + _videos.read_text()) if _videos.exists() else ""

NARRATIVE = {
    "question": """<p>The checkpoint of report 12 left one behaviour unsolved: no learned controller waits at a blocked surface with a bounded force (every controller, the tuned PD included, pushes 40 to 60 N above the 15 N cap, with an apparent stiffness of 1100 to 1450 N/m), and none presses to a target. The advisor refined the wanted response from "compliance" to an impedance: yield in proportion to the proprioceptive error, like a spring whose stiffness depends on how hard the surface is, with safety paramount (no sustained torque that heats the motors or dents the surface). The questions of this round: what exactly is that behaviour, can it be written down and executed (an oracle with privileged knowledge of the surface), can a proprioceptive controller learn it by imitation where reinforcement learning did not find it by exploration, which hardware-realisable cues carry the contact information and how fast, and does the learned behaviour remain a spring on surfaces of different stiffness?</p>
<p>Three facts make the problem hard in this setup. Proprioceptive error alone cannot distinguish a blocked tool from an unmodelled payload: training payloads reach 3 kg, about 30 N of gravity error, twice the cap; the distinguishing information is the time structure of the error and the pattern of the external torque. The policies barely sense contact: a linear probe on the trunk features of the warm start and of the stage-1 PPO arms detects contact at 75% accuracy with a median delay of 0.3 to 0.7 s. And the plant had one surface stiffness, so hardness dependence could not be measured.</p>""",
    "setup": """<p><strong>Target behaviour and oracle (ADR 0008).</strong> While the reference is inside a surface and the tool has reached it, the force pushed into the surface is a bounded spring on the actual error, push = clip(5 N + 500 N/m x e_in - d_n v_in, 5 N, 15 N), with e_in the tool's distance behind the reference along the inward normal and v_in its velocity into the surface (damping ratio 0.7 for the task-space inertia along the normal). On a rigid surface the bound is reached beyond 2 cm of error and the force stays at the cap; on a soft surface the tool sinks, the error stays small and the force stays on the linear part. In blocked references the tangential force holds the first-contact point (stop and wait); in press-and-slide references the base controller's tangential force is kept, since the slide is the task; on release the torque blends back to the base controller over 200 ms. The oracle (<code>llc/controllers/oracle.py</code>) implements this around any base controller using what a proprioceptive controller does not have: the surface location and normal, the reference's tool path, and the payload mass (an unmodelled payload presses on a table with its weight whatever the controller commands, so the oracle lifts it; a student must infer the payload from the approach). Around the shared PD it is the hardware-like ceiling of the protocol; around the frozen D3 residual it is the teacher. The impact transient of the blind approach is not the oracle's business.</p>
<p><strong>Students (stage 1).</strong> DAgger: eight iterations of 48 training episodes from the contact-focused mixture (hold 0.15, free 0.2, policy 0.1, press-and-slide 0.25, blocked 0.3; the task family held out), the teacher driving with probability 1, 0.5, 0.25 and then 0, every student decision (10 ms) labelled with the teacher's torque at that state, aggregation up to 300 k decisions, torque regression through the student's output parameterisation (per-joint gain multipliers plus a torque residual, external-torque input, warm-started from the D3 residual converted exactly), validation after every iteration on the 32 fixed cases under the cap. Variant: the same student with a 100 ms target preview (the next 10 targets, 10 ms apart, relative to the current one). Three seeds each. Stage 2 fine-tunes the students with PPO under the cap reward with the stop-and-wait anchor (the tangential kernel of blocked windows around the first-contact point) and the 500 N/m press target; a control arm resumes the D5 external-torque PPO arm with the anchored reward only.</p>
<p><strong>Protocol additions.</strong> A classical anticipatory baseline, the shared PD with the nominal inverse-dynamics feedforward of the reference, against which the preview variant must be read. Two held-out groups with the table and the wall replaced by a 2 kN/m and a 500 N/m surface (MuJoCo direct solref with a constant impedance over a 10 cm width, calibrated to about 21 N/m per unit of solref stiffness; eight cases each of the press-and-slide, blocked and task families). A new metric, contact stiffness: the mean normal force per metre of the tool's actual error along the normal while the reference is inside and the tool in contact, after the first 0.3 s; a spring on the error keeps it on every surface up to the force bound. Contact-sensing metrics: a class-balanced linear probe from a controller's trunk features to the contact state and to the blocked state (fitted on even validation cases, tested on odd ones), its balanced accuracy, the detection delay after an onset and the fraction of onsets detected within 50 and 100 ms. The cue audit applies the same probes (and a 64-unit MLP) to candidate input windows built exactly as a policy holds them, on saved episodes of the PD and of the residual, with payload-carrying free motion as negatives. Allowed cues (advisor): proprioception, the commanded torque and the link-side joint torque minus the robot's own model (the external-torque estimate); the tool-frame wrench is shelved, jerk is not used, acceleration is audited only, the payload stays unknown.</p>""",
    "extra_sections": [s for s in (STOP_SECTION, STIFF_SECTION, CUE_SECTION, SENSING_SECTION, TRAIN_SECTION, VIDEO_SECTION) if s],
    "findings": """<ol>
<li><strong>The wanted behaviour exists and the metrics see it.</strong> The oracle around the shared PD stops at a blocked surface and waits: force above the cap 2.8 N against 45.6 N for the PD, drift from the first-contact point 2 mm against 3.2 cm, moving 4% of the time in contact against 31%, apparent stiffness 314 against 1180 N/m (16 in-distribution test cases, means). It presses at 9.7 N on the press-and-slide family against 21 N, with the press deficit halved. Two things it does not fix by construction: the impact of the blind approach (sustained peak 71 N against 90 N) and the recovery after release, which is longer (1.33 s against 0.37 s) because stop-and-wait leaves the tool 2 to 5 cm behind a reference that moves away. The first version of the oracle, which did not know the payload, pressed with the payload's weight on top of its law (25 N where 9.5 N was asked on a 2 kg case): on a horizontal surface the true contact force is the commanded force plus whatever the unmodelled payload weighs, so a controller that bounds the true force must know or infer the payload.</li>
<li><strong>Imitation finds the yield that exploration did not.</strong> Eight DAgger iterations (ten minutes per seed) take the D3 residual from 57 N above the cap on blocked targets to 15 N, from 1.9 cm of drift to 4 mm, from an apparent stiffness of 1440 to 527 N/m, and from 2.4 to 0.12 for the fraction of time moving; the composite under the cap on the blocked family goes from 18.6 to 8.0, the value of the oracle around the PD (the D5 PPO arms: 14 to 17.5). On the press-and-slide family the student presses at 12 N (D3: 21 N) with 4.7 N above the cap (D3: 12.5 N) and the press deficit at 0.51 (PD 1.39); on the held-out task family it is at the cap (1.0 N above; sustained peak 19 N against 65 N for the PD). Three seeds agree (blocked composites 7.6 to 8.5). The student uses the gain head: stiffness multiplier 0.82 in contact against 0.97 free (every PPO arm stayed at 1.00), and its residual pushes 17 N away from the surface in contact against 12 N free, the lift the teacher taught it for payloads.</li>
<li><strong>The student behaves as a spring on its error, on surfaces it never saw.</strong> On the compliant held-out groups the student's contact stiffness is 552, 346 and 472 N/m on the rigid, 2 kN/m and 500 N/m surfaces, close to the teacher's 500 N/m spring and flat across surfaces, where the PD's is its own 1240, 950 and 1400 N/m; the force above the cap on blocked targets is 15.0, 1.8 and 0.6 N (PD 45.6, 15.0, 2.8). The oracle's own value rises to 755 N/m on the softest surface because its 5 N minimum force dominates at small errors, which the metric reads as stiffness.</li>
<li><strong>What it costs.</strong> The student keeps most but not all of the residual's free-space advantage: hold composite 2.33 against 1.83 (PD 3.32), free motion 0.98 against 0.71 (PD 1.01), free-motion tracking 17.9 against 13.4 mrad (PD 19.1), torque-rate RMS 80 against 45 Nm/s (PD 53); the pre-registered 5% bound on the free-space composites is not met. The distillation curves show the free-space composite rising while the teacher drives (iterations 1 to 4, up to 2.2) and recovering once the student drives (1.8 to 2.1 at iteration 8), so more student-driven iterations or a loss weighted toward the pulse windows are the obvious remedies. The hold family (10 N pulses) regresses most: a pulse is an external force, and a controller taught to yield to external forces yields to pulses too.</li>
<li><strong>Cues.</strong> With payload-carrying free motion in the fit set, every probe separates payload from contact (false positives 3 to 20%); the external-torque estimate is the only cue that detects contact fast (93 to 97% of onsets within 50 ms, balanced accuracy 0.87 to 0.89 with an MLP probe) where error and velocity reach 0.86 to 0.88 but only 61 to 78% within 50 ms; acceleration is fast (86 to 92%) but less accurate (0.80) and is not used (advisor); the target preview adds nothing to detection. On the controllers' own trunk features the linear probe is weak for every controller (balanced accuracy 0.71 to 0.76, 19 to 37% of onsets within 50 ms), students included, although the students act on contact; detectability by a linear probe is not the same as use.</li>
<li><strong>Preview and feedforward.</strong> The preview student is at parity with the base student everywhere (in-distribution mean composite 3.60 against 3.46; free-motion tracking 15.6 against 17.9 mrad), and the classical baseline, the shared PD with the nominal inverse-dynamics feedforward, improves free-motion tracking from 19.1 to 14.7 mrad on its own. The preview variant is shelved.</li>
<li><strong>Plant finding: light sliding contact is fragile.</strong> During the slide of the press-and-slide family at 9 to 15 N the sphere tool detaches 20 to 70 times per slide (gaps of 5 to 110 ms) for the oracle and the students, where the PD at 30 N detaches once; the detachments do not depend on the oracle's velocity filtering, force projection or update rate, nor on the contact boundary's softness (a stiffer boundary makes the 35 N PD detach too), and they do not occur on the compliant surfaces. The contact-loss metric therefore penalises the capped behaviour on the two sliding families (student 11.9 losses per second against 4.3 for the PD); the blocked family, where nothing slides, is the primary evidence.</li>
<li><strong>Stage 2: PPO adds nothing to imitation here.</strong> 150 PPO updates under the cap reward with the stop-and-wait anchor and the 500 N/m press target, from each student (25 minutes per seed): the training return rises from 12 to 25 while the validation composite does not follow. For two of three seeds the selected checkpoint is the student itself (every validation point of the run is worse, 3.6 to 5.7 against 3.43 and 3.55); the third improves from 3.61 to 3.45 at update 124 (blocked 9.1 to 7.3, excess force 1.1 to 0.6 N) and relapses by update 149. What PPO changes is consistent across seeds: forces fall further (excess above the cap 0.4 to 0.8 N on validation) while the hold, step and task families degrade, the same trade that D5 found. The control arm, the D5 external-torque arm with only the anchored reward, moves from 4.66 to 4.42 by update 74 (blocked 16.6 to 14.4) and no further: the reward change alone does not produce stop-and-wait in 150 updates. On the test tables the selected checkpoints (three seeds pooled) are at parity with the students: blocked composite 8.4 against 8.0, force above the cap 15.3 against 15.0 N, sustained peak 66 against 72 N, apparent stiffness 518 against 527 N/m; in-distribution mean composite 3.53 against 3.46, and the same picture on every held-out group. The control arm gets part of the way on its own (blocked excess 53 to 36 N, apparent stiffness 1350 to 1000 N/m, blocked composite 17.5 to 13.6) at a cost in free space (torque rate 115 Nm/s) and is far from the student's 8.0. For this behaviour the recipe is imitation of the oracle; reinforcement learning under the cap reward neither finds it from the D5 warm start in 150 updates nor improves it once found.</li>
</ol>""",
    "caveats": """<ul>
<li>The oracle and the teacher are privileged: they know the surface, the reference's tool path and the payload mass. The students see proprioception, the commanded torque, the external-torque estimate and the position target; whether their payload inference holds beyond 3 kg or for payloads that change during an episode is untested.</li>
<li>The 15 N cap puts the task family's 30 N-class presses out of scope by design; the students' task press deficit (1.7) reflects that, not a failure to press.</li>
<li>The recovery metric after a blocked release penalises stop-and-wait by construction (the tool has further to go); it was defined before this round and is kept, but its weight in the blocked composite (1 per 0.3 s) is larger than the drift's (1 per 2 cm), so the composite understates the oracle's advantage.</li>
<li>The compliant surfaces are calibrated on the table (within 10%); the wall's effective stiffness is within a factor 1.5 of the nominal value because its effective mass differs.</li>
<li>Validation inside the trainers uses 32 cases; every ranking above comes from the 16-case test tables, three seeds for the students. The stage-1 PPO arms of D5 are one seed for the external-torque arm in these tables.</li>
</ul>""",
    "next": """<ul>
<li>Imitation of the oracle is the recipe for this behaviour; the next training rounds start from the distilled students, and PPO stays a tool for what imitation cannot specify (the free-space trade-offs), with the reward audited against the protocol first.</li>
<li>Recover the free-space advantage: more student-driven DAgger iterations, or the label loss weighted toward the hold and pulse windows, or a free-space regulariser toward the warm start.</li>
<li>A contact model with a finite patch (or a different tool) to settle whether the light-contact detachments are physical; it is the plant's next revision.</li>
<li>An explicit learned estimate of the dynamic mode (free, contact, blocked, sliding, payload) as a policy input, with the probe metrics as its validation (advisor, later round); the tool-frame wrench stays shelved.</li>
</ul>""",
}
